// ── Normalize Place ───────────────────────────────────────────────
// Merapikan output Serper /places jadi bentuk yang konsisten.
// Node ini TIDAK memanggil internet. Cuma bersih-bersih data.

const params = $('Set Search Params').first().json;

function toE164ID(raw) {
  if (!raw) return '';
  let d = String(raw).replace(/[^\d+]/g, '');
  if (d.startsWith('+62')) d = d.slice(1);
  else if (d.startsWith('62')) { /* sudah benar */ }
  else if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('8')) d = '62' + d;
  else return '';
  d = d.replace(/\D/g, '');
  if (!/^62\d{8,13}$/.test(d)) return '';
  return '+' + d;
}

function originOf(url) {
  try { return new URL(String(url)).origin; } catch (e) { return ''; }
}

function domainOf(url) {
  try { return new URL(String(url)).hostname.replace(/^www\./i, '').toLowerCase(); }
  catch (e) { return ''; }
}

// Kota yang kita sapu. 'Batu' didahulukan dari 'Malang' karena baseCityOf()
// mencocokkan dengan includes(), bukan sama-persis.
const KNOWN_CITIES = ['Surabaya', 'Sidoarjo', 'Gresik', 'Mojokerto', 'Batu', 'Malang'];

// 'Rungkut Surabaya' dan 'Surabaya Timur' itu kata kunci pencarian, bukan kota.
// Kota dasarnya dipakai sebagai cadangan kalau alamat tidak menyebut kota.
function baseCityOf(searchLocation) {
  const s = String(searchLocation || '').toLowerCase();
  for (const city of KNOWN_CITIES) {
    if (s.indexOf(city.toLowerCase()) !== -1) return city;
  }
  return String(searchLocation || '').trim();
}

// Google mengembalikan 'Jl. Raya Rungkut ..., Rungkut, Surabaya, Jawa Timur 60293'.
// Kota diambil dari SITU, bukan dari query. Itulah yang bikin satu bisnis
// tersimpan dengan satu kota apa pun kata kunci yang menemukannya — syarat
// strategi dedupe fuzzy nama+kota supaya tetap bekerja lintas sapuan.
function cityFromAddress(address, fallback) {
  const parts = String(address || '').split(',');
  for (const part of parts) {
    const bare = part
      .trim()
      .replace(/^(kota|kab\.?|kabupaten)\s+/i, '')
      .replace(/\s+\d{5}$/, '')
      .trim();
    for (const city of KNOWN_CITIES) {
      if (bare.toLowerCase() === city.toLowerCase()) return city;
    }
  }
  return fallback;
}

// example.invalid dijamin gagal resolve (RFC 2606) -> ditangkap onError,
// jadi item tetap keluar 1:1 dan urutan tidak bergeser.
const DEAD = 'https://no-website.invalid';

const fallbackCity = baseCityOf(params.lokasi);

return $input.all().map((item, i) => {
  const p = item.json || {};
  const website = p.website || '';
  const origin = originOf(website);
  const domain = domainOf(website);
  const telepon = toE164ID(p.phoneNumber);

  return {
    json: {
      nama_bisnis: p.title || '',
      kategori: p.category || '',
      alamat: p.address || '',
      kota: cityFromAddress(p.address, fallbackCity),
      // Kata kunci lokasi yang menemukan bisnis ini — provenance, bukan identitas.
      kota_pencarian: params.lokasi || '',
      website: website,
      domain: domain,
      origin: origin,
      telepon_gmaps: telepon,
      is_mobile: /^\+628/.test(telepon),
      rating: p.rating != null ? p.rating : '',
      jumlah_review: p.ratingCount != null ? p.ratingCount : '',
      maps_cid: p.cid || '',
      dedupe_key: domain || telepon || String(p.title || '').toLowerCase().trim(),
      // URL untuk 2 node fetch berikutnya
      url_home: origin || DEAD,
      url_contact: origin ? origin + '/contact' : DEAD,
    },
    pairedItem: i,
  };
});

// ── Extract Contacts ──────────────────────────────────────────────
// Gabungkan metadata Google Maps + HTML homepage + HTML halaman kontak.
// Pakai index (bukan Merge node) karena setiap node fetch di-set
// onError=continueRegularOutput, jadi jumlah item selalu 1:1 dan urut.

const meta = $('Normalize Place').all();
const items = $input.all();

// Fetch Website / Fetch Contact Page dimatikan selama sapuan volume — dua node
// itu yang memakan waktu, dan di segmen ini nyaris tidak menghasilkan apa-apa
// (0 dari 11 perusahaan impor pertama punya website).
//
// Node yang di-Deactivate meneruskan item apa adanya, jadi meta tetap 1:1 dengan
// $input dan blob HTML-nya sekadar kosong. $() sendiri bisa melempar kalau node
// itu dicabut dari alur, bukan cuma dimatikan — makanya dibungkus.
function safeAll(nodeName) {
  try { return $(nodeName).all(); } catch (e) { return []; }
}

const home = safeAll('Fetch Website');
const contact = safeAll('Fetch Contact Page');

function htmlAt(list, i) {
  const entry = list[i];
  if (!entry || !entry.json) return '';
  return String(entry.json.data || '');
}

const NOISE_LOCAL = /^(no-?reply|donotreply|postmaster|abuse|webmaster|mailer-daemon|privacy|dpo|example|your|email|name|user|username|sentry|wix|u003)/i;
const NOISE_DOMAIN = /(sentry\.io|wixpress|godaddy|squarespace|shopify|example\.(com|org|net)|yourdomain|yoursite|domain\.com|email\.com|sample\.com|test\.com|\.png|\.jpe?g|\.gif|\.svg|\.webp|\.css|\.js|\.woff)/i;

function toText(h) {
  return String(h || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&#0?64;|&commat;/gi, '@')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ');
}

function normPhone(raw) {
  let d = String(raw).replace(/\D/g, '');
  if (d.startsWith('62')) { /* ok */ }
  else if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('8')) d = '62' + d;
  else return '';
  if (!/^628\d{7,12}$/.test(d)) return '';
  return '+' + d;
}

function grabEmails(rawHtml) {
  const raw = String(rawHtml || '');
  const found = new Set();

  // 1. mailto: -> presisi paling tinggi
  const mailtos = raw.match(/mailto:([^"'?>\s\\]+)/gi) || [];
  for (const m of mailtos) {
    try { found.add(decodeURIComponent(m.replace(/^mailto:/i, ''))); } catch (e) { /* skip */ }
  }

  // 2. teks polos (HTML sudah di-strip dulu, kalau tidak akan kena URL aset)
  const plain = toText(raw).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  for (const m of plain) found.add(m);

  const valid = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
  return [...found]
    .map(function (e) { return e.trim().toLowerCase().replace(/[.,;:)\]]+$/, ''); })
    .filter(function (e) {
      if (!valid.test(e)) return false;
      if (NOISE_DOMAIN.test(e)) return false;
      if (NOISE_LOCAL.test(e.split('@')[0])) return false;
      return true;
    });
}

function grabPhones(rawHtml) {
  const text = toText(rawHtml).replace(/[\u2010-\u2015\u00A0]/g, '-');
  const re = /(?:\+?62|0)[\s.\-]?8\d{1,3}(?:[\s.\-]?\d{2,4}){2,4}/g;
  const out = new Set();
  const hits = text.match(re) || [];
  for (const h of hits) {
    const n = normPhone(h);
    if (n) out.add(n);
  }
  return [...out];
}

function pickEmail(emails, domain) {
  if (!emails.length) return '';
  function score(e) {
    const parts = e.split('@');
    const local = parts[0];
    const dom = parts[1] || '';
    let s = 0;
    if (domain && dom === domain) s += 100;
    if (domain && dom.endsWith('.' + domain)) s += 80;
    if (/^(sales|marketing|info|contact|kontak|cs|customer|order|halo|hello|admin)/.test(local)) s += 20;
    if (/(gmail|yahoo|hotmail|outlook|icloud)\./.test(dom)) s -= 15;
    if (local.length > 30) s -= 10;
    return s;
  }
  return emails.slice().sort(function (a, b) { return score(b) - score(a); })[0];
}

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
const seen = new Set();
const results = [];

for (let i = 0; i < items.length; i++) {
  const m = (meta[i] && meta[i].json) || {};
  const blob = htmlAt(home, i) + ' ' + htmlAt(contact, i);

  const emails = grabEmails(blob);
  const phones = grabPhones(blob);

  const email = pickEmail(emails, m.domain);
  const telepon = m.telepon_gmaps || phones[0] || '';
  const whatsapp = m.is_mobile ? m.telepon_gmaps : (phones[0] || '');

  // Buang yang tidak punya jalur kontak sama sekali - itu bukan lead.
  if (!email && !telepon && !m.website) continue;

  // Dedupe dalam satu run
  const key = m.dedupe_key || String(m.nama_bisnis || '').toLowerCase();
  if (!key || seen.has(key)) continue;
  seen.add(key);

  results.push({
    json: {
      'Nama Bisnis': m.nama_bisnis || '',
      'Kategori': m.kategori || '',
      'Alamat': m.alamat || '',
      'Kota': m.kota || '',
      'Website': m.website || '',
      'Email': email,
      'Email Lain': emails.filter(function (e) { return e !== email; }).slice(0, 3).join('; '),
      'No. Telepon': telepon,
      'WhatsApp': whatsapp,
      'Rating': m.rating,
      'Jumlah Review': m.jumlah_review,
      'Sumber': 'Google Maps via Serper',
      'Tanggal Ambil': now,
      maps_cid: m.maps_cid || '',
      kota_pencarian: m.kota_pencarian || '',
      dedupe_key: key,
    },
    pairedItem: i,
  });
}

return results;

// ── Build SORA Payload ───────────────────────────────────────────────────────
// Maps the sheet-shaped output of Extract Contacts onto the API contract in
// docs/SPEC.md §2, then signs it.
//
// Sheet headers ("Nama Bisnis") are a presentation format. The API speaks one
// canonical shape so that n8n, CSV upload and anything added later all land in
// the same pipeline.
//
// THIS NODE MUST ALWAYS RETURN EXACTLY ONE ITEM. `Send to SORA` loops back into
// `Loop Over Searches`, so a node that returns nothing ends the sweep: the loop
// is never told to fetch the next search. A search that found nothing is normal
// — Serper answers `places: []` for plenty of queries — and it must cost that
// one search, not the 239 behind it. So an empty batch is still posted, and SORA
// answers `accepted: 0`.

// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto, which docker-compose.n8n.yml sets.
const crypto = require('crypto');

const config = $('SORA Config').first().json;
const SECRET = config.webhook_secret;
const CAMPAIGN_ID = config.campaign_id;

if (!SECRET) throw new Error('SORA Config: webhook_secret is empty — is SORA_WEBHOOK_SECRET set on the container?');
if (!CAMPAIGN_ID) throw new Error('SORA Config: campaign_id is empty — run `pnpm campaign:create` and set SORA_CAMPAIGN_ID');

// `SORA Config` is a Set node with includeOtherFields, so it stamps its own
// assignments onto EVERY item that passes through it -- and this node used to
// copy the whole item into `raw`. That is how the live HMAC secret ended up in
// plaintext on 1208 company rows and 669 webhook_events payloads.
//
// The config is read from the node directly (above), never from the item, so
// nothing here needs these keys. Add a name to this list whenever you add an
// assignment to SORA Config.
const CONFIG_KEYS = ['webhook_secret'];

function withoutConfig(item) {
  const copy = Object.assign({}, item);
  for (const key of CONFIG_KEYS) delete copy[key];
  return copy;
}

function clean(value) {
  const s = String(value ?? '').trim();
  return s === '' ? null : s;
}

// Serper leaves rating and ratingCount empty for a place nobody has reviewed,
// and Normalize Place passes '' straight through. '' is not 0 -- 0 would claim
// we measured a rating of zero -- so anything unparseable becomes null and
// src/lib/scoring/signals.ts scores that factor neutral.
function num(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

const items = $input.all()
  .map((item) => {
    const j = item.json || {};

    // Google Maps provenance, so "where did this lead come from" stays answerable.
    const cid = clean(j.maps_cid);
    const sourceUrl = cid ? `https://www.google.com/maps?cid=${cid}` : clean(j.Website);

    return {
      company_name: String(j['Nama Bisnis'] ?? '').trim(),
      category: clean(j['Kategori']),
      address: clean(j['Alamat']),
      city: clean(j['Kota']),
      website: clean(j['Website']),
      email: clean(j['Email']),
      phone: clean(j['No. Telepon']),
      whatsapp: clean(j['WhatsApp']),
      // The two strongest inputs to lead classification. They have always ridden
      // along inside `raw`, keyed by an Indonesian sheet header; sending them as
      // contract fields is what lets them land in real columns instead of needing
      // a backfill after every sweep.
      rating: num(j['Rating']),
      review_count: num(j['Jumlah Review']),
      source_url: sourceUrl,
      // Everything else rides along for debugging and re-processing -- minus
      // whatever SORA Config stamped on, which is credentials, not lead data.
      raw: withoutConfig(j),
    };
  })
  // `Extract Contacts` runs with alwaysOutputData, so a search that found nothing
  // arrives here as one empty placeholder item. Drop it rather than posting a
  // nameless company SORA would only reject.
  .filter((item) => item.company_name !== '');

// One key per run, computed once. A retry of THIS run must reuse it — that is
// what makes a redelivery insert nothing. A new search gets a new key.
const params = $('Set Search Params').first().json;
const stamp = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
const slug = `${params.keyword}-${params.lokasi}-p${params.page ?? 1}`.toLowerCase().replace(/[^a-z0-9]+/g, '-');
const idempotencyKey = `run_${slug}_${stamp}`;

const payload = {
  campaign_id: CAMPAIGN_ID,
  source: 'serper_places',
  idempotency_key: idempotencyKey,
  items,
};

// Sign the string that will actually be sent, and send this exact string.
const body = JSON.stringify(payload);
const signature =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(body, 'utf8').digest('hex');

return [{ json: { body, signature, item_count: items.length, idempotency_key: idempotencyKey } }];

// ── Search Plan ──────────────────────────────────────────────────────────────
// The only place you edit for a bigger sweep. One Execute runs ONE DAY'S SLICE
// of the space below, one search at a time, each landing in SORA separately.
//
// Why a slice and not the whole space every day: a week of scraping is a
// measurement. Re-running every combination daily spends Serper credits to
// rediscover rows that dedupe merges anyway. Combination i belongs to slice
// i % SLICES, so a day gets a MIX of keywords and cities rather than one city,
// and the whole space is covered evenly as the week goes on.
//
// MEASURED: Serper /places returns **10** results per request, not 20. Four
// stored executions (2026-09-01 to 2026-09-06) and then 25 more on 2026-09-07
// each returned at most 10 while `num` asked for 20, and Extract Contacts
// dropped none of them — so the shortfall is Serper, not our contact filter.
//
// PAGES is therefore the ONLY lever that gets a city past 10 results:
// [1, 2, 3, 4, 5] gives up to 50.
//
// ALSO MEASURED: a query can come back empty for no reason and answer normally
// minutes later, so roughly one search in eight yields nothing. That is why
// Extract Contacts runs with alwaysOutputData and Build SORA Payload always
// returns one item — a nil search must cost one search, not the rest of the day.

const KEYWORDS = [
  'pet shop',
  'petshop',
  'toko hewan peliharaan',
  'toko pakan hewan',
  'grooming hewan',
  'pet grooming',
  'klinik hewan',
  'dokter hewan',
  'toko kucing',
  'toko anjing',
  'aksesoris hewan peliharaan',
  'penitipan hewan',
];

// Surabaya raya. The kecamatan-level entries are here because Google biases
// /places by the text of the query: 'pet shop Rungkut Surabaya' surfaces shops
// that 'pet shop Surabaya' never reaches, page 5 included.
//
// PROBED 2026-09-07, one search each: 22 of these 25 returned 10 results,
// Kenjeran returned 5, and Gubeng / Waru / Manyar returned none. The three
// empties are NOT bad location strings — 'Surabaya Pusat' returned nothing an
// hour earlier and 10 on the probe, so Serper answers empty intermittently for
// any query. They stay in the list; the sweep survives an empty now.
const KOTA = [
  'Surabaya',
  'Surabaya Pusat',
  'Surabaya Barat',
  'Surabaya Timur',
  'Surabaya Selatan',
  'Surabaya Utara',
  'Rungkut Surabaya',
  'Gubeng Surabaya',
  'Wiyung Surabaya',
  'Lakarsantri Surabaya',
  'Mulyorejo Surabaya',
  'Tandes Surabaya',
  'Kenjeran Surabaya',
  'Wonokromo Surabaya',
  'Sukolilo Surabaya',
  'Sidoarjo',
  'Waru Sidoarjo',
  'Taman Sidoarjo',
  'Krian Sidoarjo',
  'Gresik',
  'Manyar Gresik',
  'Mojokerto',
  'Malang',
  'Malang Kota',
  'Batu',
];

const PAGES = [1, 2, 3, 4, 5];

// 10, not 20. Serper bills ONE credit for a request asking up to 10 results and
// TWO for 11-100, so `20` doubled the price of every search in the sweep -- and
// bought nothing, because the measurement above is that Serper returns at most
// 10 regardless of what `num` asks. PAGES is the only lever past 10 for a city.
const JUMLAH = 10;
const NEGARA = 'id';

// 6, not 7, on purpose: day 7 lands back on slice 0. Re-covering the ground the
// week opened with is what measures how fast new businesses actually appear.
const SLICES = 6;

// The first day of the sweep. Fixed, so "which slice runs today" is reproducible
// and does not drift with the container's uptime. Move it if the week slips.
const START_DATE = '2026-09-07';

// Hard ceiling on Serper credits per Execute. The free tier is ~2500 ONCE for
// the life of the account -- it does not refill weekly or monthly; a widened
// KEYWORDS list that quietly doubles the plan would spend it in two days, and
// the failure would look like "Serper stopped working".
const MAX_SEARCHES_PER_DAY = 260;

// Days since epoch in the container's own timezone (Asia/Jakarta, set by
// docker-compose.n8n.yml). Not UTC — that would roll the slice over at 07:00
// local, in the middle of the scheduled run.
function localDayNumber(date) {
  const shifted = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return Math.floor(shifted.getTime() / 86400000);
}

const dayIndex = localDayNumber(new Date()) - localDayNumber(new Date(START_DATE + 'T00:00:00'));
const slice = ((dayIndex % SLICES) + SLICES) % SLICES; // negative-safe: a run before START_DATE still picks a valid slice

const all = [];
for (const keyword of KEYWORDS) {
  for (const lokasi of KOTA) {
    for (const page of PAGES) {
      all.push({ keyword, lokasi, page, jumlah: JUMLAH, negara: NEGARA });
    }
  }
}

if (all.length === 0) throw new Error('Search Plan is empty — fill KEYWORDS and KOTA');

const chosen = all.filter(function (_, i) { return i % SLICES === slice; });

if (chosen.length > MAX_SEARCHES_PER_DAY) {
  console.log(
    'Search Plan: slice ' + slice + ' has ' + chosen.length + ' searches, capped at ' +
    MAX_SEARCHES_PER_DAY + '. Shrink KEYWORDS/KOTA/PAGES or raise the cap deliberately.'
  );
}

return chosen.slice(0, MAX_SEARCHES_PER_DAY).map(function (params) {
  return {
    json: Object.assign({}, params, {
      slice: slice,
      day_index: dayIndex,
      plan_size: all.length,
    }),
  };
});

// ── Run Summary ──────────────────────────────────────────────────────────────
// The loop's "done" output carries what every iteration returned — one response
// from SORA per search. Totals here, details in the individual Send to SORA runs.

let accepted = 0, inserted = 0, duplicates = 0, rejected = 0, replayed = 0;

for (const item of $input.all()) {
  const j = item.json || {};
  accepted   += j.accepted   || 0;
  inserted   += j.inserted   || 0;
  duplicates += j.duplicates || 0;
  rejected   += Array.isArray(j.rejected) ? j.rejected.length : 0;
  if (j.replayed) replayed += 1;
}

return [{ json: { searches: $input.all().length, accepted, inserted, duplicates, rejected, replayed } }];
